import { Mobject } from "../../mobject/mobject.js";
import { _normalize_flat } from "../../utils/space_ops.js";
import { clip } from "../../utils/simple_functions.js";
import { isNDArray, pointRows } from "../../utils/arrays.js";
import { RIGHT } from "../../constants.js";
export function bind_mobject_method(mobject, name) {
    const method = mobject[name];
    if (typeof method !== "function")
        throw new Error(`Mobject has no method '${name}'`);
    // NOTE: mirrors a CPython bound method: the facade carries `__self__` /
    // `__func__` so it passes `ApplyMethod.check_validity_of_input` (and the
    // `Scene.play` bound-method rejection) exactly like Python's
    // `mobject.method`. `mobject`/`originalMethod` are kept for `always` /
    // `f_always` (the port's historical spelling).
    const bound = method.bind(mobject);
    bound.__self__ = mobject;
    bound.__func__ = method;
    bound.mobject = mobject;
    bound.originalMethod = method;
    return bound;
}
export function assert_is_mobject_method(method) {
    return assertMobjectMethod(method);
}
function assertMobjectMethod(method) {
    const mobject = method.mobject;
    if (!(mobject instanceof Mobject))
        throw new Error("Expected a mobject method");
    return mobject;
}
export function always(method, ...args) {
    const mobject = assertMobjectMethod(method);
    const function_ = method.originalMethod ?? method;
    mobject.add_updater((mob) => function_.call(mob, ...args));
    return mobject;
}
export function f_always(method, ...arg_generators) {
    const mobject = assertMobjectMethod(method);
    const function_ = method.originalMethod ?? method;
    const updater = (mob) => {
        const args = arg_generators.map((generator) => generator());
        function_.call(mob, ...args);
    };
    mobject.add_updater(updater);
    return mobject;
}
export function always_redraw(func) {
    const mob = func();
    mob.add_updater((mob) => mob.become(func()));
    return mob;
}
export function turn_animation_into_updater(animation, cycle = false, delay = 0, kwargs = {}) {
    // NOTE: mirrors Python, whose **kwargs are accepted but never used.
    void kwargs;
    const mobject = animation.mobject;
    animation.suspend_mobject_updating = false;
    animation.begin();
    animation.total_time = -delay;
    function update(m, dt) {
        if (animation.total_time >= 0) {
            const run_time = animation.get_run_time();
            // handle zero/negative runtime safely
            if (run_time <= 0) {
                // instantly snap to final state once, then remove updater
                animation.interpolate(1);
                animation.update_mobjects(dt);
                animation.finish();
                m.remove_updater(update);
                return;
            }
            const time_ratio = animation.total_time / run_time;
            let alpha;
            if (cycle) {
                alpha = time_ratio % 1;
            }
            else {
                alpha = clip(time_ratio, 0, 1);
                if (alpha >= 1) {
                    animation.finish();
                    m.remove_updater(update);
                    return;
                }
            }
            animation.interpolate(alpha);
            animation.update_mobjects(dt);
        }
        animation.total_time += dt;
    }
    mobject.add_updater(update);
    return mobject;
}
export function cycle_animation(animation, kwargs = {}) {
    return turn_animation_into_updater(animation, true, 0, kwargs);
}
export function always_shift(mobject, direction = RIGHT, rate = 0.1) {
    const directionArray = isNDArray(direction)
        ? (pointRows(direction, 3)[0] ?? [0, 0, 0])
        : [...direction];
    const unit = _normalize_flat(directionArray);
    mobject.add_updater((m, dt) => {
        m.shift(unit.map((value) => dt * rate * value));
    });
    return mobject;
}
